    @render.ui
    def record_details():
        if not details_open.get():
            return None

        df = filtered_data()
        selection = data_table.cell_selection()
        if selection["type"] == "none" or not selection["rows"]:
            return ui.div(
                _record_details_header(),
                ui.p("Select a row in the table to view all of its details."),
                class_="record-details",
            )

        row_number = selection["rows"][0]
        if row_number < 0 or row_number >= len(df):
            return ui.div(
                _record_details_header(),
                ui.p("The selected record is no longer available. Select another row."),
                class_="record-details",
            )

        row = df.iloc[row_number]
        hidden_columns = {"Parameter (unit)", "Suggested metadata"}
        ordered_columns = [c for c in row.index if c not in hidden_columns and c != "Unit"]
        if "Unit" in row.index:
            insert_at = ordered_columns.index("Value") + 1 if "Value" in ordered_columns else len(ordered_columns)
            ordered_columns.insert(insert_at, "Unit")

        detail_rows = []
        for column in ordered_columns:
            value = row[column]
            display_value = "" if pd.isna(value) else str(value)
            detail_rows.append(
                ui.div(
                    ui.tags.dt(str(column)),
                    ui.tags.dd(display_value),
                    class_="record-detail-row",
                )
            )

        return ui.div(
            _record_details_header(),
            ui.tags.dl(*detail_rows),
            class_="record-details",
        )

